	": Buchungen, Belege und Zuordnungen dieses Jahres können nicht mehr geändert oder gelöscht werden – z. B. nach der Kassenprüfung und Entlastung. Nur Verwalter können ein Jahr abschließen oder wiedereröffnen; beides wird im Protokoll (Berichte → Protokoll) festgehalten.": ": boekingen, bewijsstukken en toewijzingen voor dit jaar kunnen niet meer worden gewijzigd of verwijderd – bijv. na de kascontrole en decharge. Alleen beheerders kunnen een jaar afsluiten of heropenen; beide acties worden vastgelegd in het logboek (Rapporten → Logboek).",
