	"Damit ordnet die App importierte Kontoauszüge dem richtigen Konto zu (bei mehreren Geldkonten), und Rechnungen nennen die Bankverbindung. Leerzeichen sind egal.": "Hiermee wijst de app geïmporteerde bankafschriften toe aan de juiste rekening (als er meerdere geldrekeningen zijn), en facturen vermelden deze als bankgegevens. Spaties maken niet uit.",
