	"Konto aktiv": "Rekening actief",
	"Ein inaktives Konto verschwindet aus allen Auswahllisten – bereits gebuchte Beträge, Berichte und die Historie bleiben unverändert. So werden Konten losgeworden, die sich wegen vorhandener Buchungen nicht löschen lassen.": "Een inactieve rekening verdwijnt uit alle keuzelijsten – reeds geboekte bedragen, rapporten en de geschiedenis blijven ongewijzigd. Zo ruimt u rekeningen op die niet kunnen worden verwijderd omdat er al boekingen op staan.",
	"Verein": "Vereniging",
	"Vereinsname (erscheint im Kopf des Kassenberichts)": "Verenigingsnaam (verschijnt in de kop van het kasverslag)",
	"z. B. Musterverein e. V.": "bijv. Voorbeeldvereniging e. V.",
	"Corporate Design": "Huisstijl",
	"Logo und Akzentfarbe erscheinen im Kurzbericht für Vorstandssitzungen (Berichte → Auswertung).": "Logo en accentkleur verschijnen in het korte rapport voor bestuursvergaderingen (Rapporten → Analyse).",
	"Logo wählen": "Logo kiezen",
	"Vereinslogo": "Verenigingslogo",
	"kein Logo hinterlegt": "geen logo ingesteld",
	"Entfernen": "Verwijderen",
	"Akzentfarbe": "Accentkleur",
	"Auswertungsgruppen-Modus": "Modus rapportagegroepen",
	"Bestimmt, wie der Bericht „Auswertungsgruppen\" die Konten gruppiert. Die ersten beiden Modi lesen die Auswertungsgruppe aus dem Kontenrahmen ab und setzen voraus, dass er dafür gebaut ist. Der dritte macht diese Annahme nicht: Auswertungsgruppen werden angelegt und Konten ihnen ausdrücklich zugeordnet (Abschnitt „Auswertungsgruppen\" weiter oben).": "Bepaalt hoe het rapport “Rapportagegroepen” rekeningen groepeert. De eerste twee modi lezen de rapportagegroep af uit het rekeningschema en gaan ervan uit dat het daarvoor is opgezet. De derde gaat daar niet van uit: rapportagegroepen worden aangemaakt en rekeningen worden er expliciet aan toegewezen (zie het onderdeel “Rapportagegroepen” hierboven).",
	"Modus": "Modus",
	"2. Zahlengruppe der Kontonummer (z. B. „111 51\" → Auswertungsgruppe 51)": "2e cijfergroep van het rekeningnummer (bijv. “111 51” → rapportagegroep 51)",
	"Jedes Einnahmen-/Ausgabenkonto ist eine eigene Auswertungsgruppe": "Elke inkomsten-/uitgavenrekening is een eigen rapportagegroep",
	"Frei definierte Auswertungsgruppen (Konten werden zugeordnet)": "Vrij gedefinieerde rapportagegroepen (rekeningen worden toegewezen)",
	"Belegablage": "Opslag bewijsstukken",
	"Nextcloud-Nutzer": "Nextcloud-gebruiker",
	"Ordnerpfad im Nutzer-Home": "Mappad in de thuismap van de gebruiker",
	"Belege werden unter": "Bewijsstukken worden onder",
	"abgelegt.": "opgeslagen.",
	"Kontoauszüge automatisch einlesen": "Bankafschriften automatisch importeren",
	"Legt man den im Onlinebanking heruntergeladenen Kontoauszug in diesen Ordner, liest die App ihn von allein ein – kein Hochladen mehr von Hand. Erkannt werden CSV-CAMT, CAMT.053 (XML) und MT940. Leer lassen schaltet die Funktion ab.": "Als u het bij internetbankieren gedownloade bankafschrift in deze map plaatst, leest de app het automatisch in – geen handmatige uploads meer. CSV-CAMT, CAMT.053 (XML) en MT940 worden herkend. Laat leeg om de functie uit te schakelen.",
	"— aus —": "— uit —",
