	"Geldbestand": "Geldmiddelen",
	"Oben rechts steht jetzt der Geldbestand aller Geldkonten zusammen, nicht mehr nur der des ersten Kontos. Die Aufschlüsselung nach Konten zeigt der Tooltip, wenn die Maus auf der Zahl steht.": "Rechtsboven staan nu de geldmiddelen van alle geldrekeningen samen, niet meer alleen die van de eerste rekening. Beweeg de muis over het bedrag en de tooltip toont de uitsplitsing per rekening.",
	"Ein einzelnes Geldkonto lässt sich aus dieser Zahl herausnehmen – im Konto-Dialog über „Zählt in den Geldbestand oben in der Kopfzeile\". Kassenbericht, Vermögensübersicht und Saldenliste rechnen unverändert mit allen Geldkonten.": "Een afzonderlijke geldrekening kan uit dit bedrag worden weggelaten – in het rekeningdialoogvenster via “Telt mee voor de geldmiddelen in de kopregel”. Het kasverslag, het vermogensoverzicht en de proefbalans blijven alle geldrekeningen meetellen.",
	"{amount} noch nicht zugeordnet": "{amount} nog niet toegewezen",
	"_%n Geldkonto zählt hier nicht mit – alle zusammen: {amount}_::_%n Geldkonten zählen hier nicht mit – alle zusammen: {amount}_": [
		"%n geldrekening telt hier niet mee – alles samen: {amount}",
		"%n geldrekeningen tellen hier niet mee – alles samen: {amount}"
	],
