	"Zählt in den Geldbestand oben in der Kopfzeile": "Telt mee voor de geldmiddelen in de kopregel",
	"Dieses Konto bleibt aus der Zahl oben in der Kopfzeile heraus – sinnvoll z. B. bei einem Festgeldkonto, das nicht zum Tagesgeschäft gehört. In Kassenbericht, Vermögensübersicht und Saldenliste zählt es unverändert mit.": "Deze rekening blijft buiten het bedrag in de kopregel – handig bijvoorbeeld voor een deposito die niet tot de dagelijkse gang van zaken hoort. In het kasverslag, het vermogensoverzicht en de proefbalans telt ze gewoon mee.",
