	"Beiträge & SEPA": "Contributies & SEPA",
	"Optionales Zusatzmodul: wer keine Lastschriften einzieht, kann diesen Bereich ignorieren.": "Optionele module: als u geen incasso's int, kunt u dit onderdeel negeren.",
	"Einstellungen → SEPA-Lastschriftmandate: je Zahler ein Mandat mit IBAN und Unterschriftsdatum. Zahler ist ein Nextcloud-Nutzer oder ein frei eingetragener Name.": "Instellingen → SEPA-incassomachtigingen: één machtiging per betaler, met IBAN en datum van ondertekening. Een betaler is een Nextcloud-gebruiker of een vrij ingevoerde naam.",
	"Einstellungen → Mitgliedsbeiträge: Betrag und Frequenz festlegen – bei Fälligkeit entsteht automatisch ein offener Posten, mit oder ohne Mandat.": "Instellingen → Contributies: bedrag en frequentie instellen – zodra een contributie verschuldigd is, wordt automatisch een openstaande post aangemaakt, met of zonder machtiging.",
	"Einstellungen → SEPA-Sammeleinzug: Vorschau prüfen, Einzug erzeugen und die XML-Datei bei der Hausbank einreichen. Vor dem ersten Einzug mit dem Prüftool der Bank testen.": "Instellingen → SEPA-incasso: controleer het voorbeeld, maak de incasso aan en lever het XML-bestand in bij uw bank. Test het met de validatietool van uw bank vóór de eerste echte incasso.",
	"Ein Mandat wird widerrufen, nicht gelöscht – erzeugte Einreichungen müssen nachvollziehbar bleiben.": "Een machtiging wordt ingetrokken, niet verwijderd – reeds aangemaakte aanleveringen moeten herleidbaar blijven.",
	"{n} mögliche SEPA-Rücklastschrift(en) erkannt: bitte im Bankabgleich (Beiträge → Einzug) prüfen und verbuchen.": "{n} mogelijke gestorneerde SEPA-incasso('s) herkend: controleer en verwerk ze in de bankafstemming (Contributies → Incasso).",
	"Mitgliedsbeiträge": "Contributies",
	"Wiederkehrende Beiträge mit Zahlungsfrequenz. Bei Fälligkeit legt die App automatisch einen offenen Posten an (Berichte → Offene Posten) – unabhängig davon, ob ein SEPA-Mandat verknüpft ist. Ohne Mandat ist der Posten einfach eine Erinnerung, z. B. für eine erwartete Überweisung.": "Terugkerende contributies met een betalingsfrequentie. Zodra een contributie verschuldigd is, maakt de app automatisch een openstaande post aan (Rapporten → Openstaande posten) – ongeacht of er een SEPA-machtiging aan gekoppeld is. Zonder machtiging is de post gewoon een herinnering, bijvoorbeeld voor een verwachte overschrijving.",
