	"Rückgängig: {name}": "Ongedaan maken: {name}",
	"Die Buchung ist gespeichert, aber diese Belege ließen sich nicht entfernen: {names} ({grund}).": "De boeking is opgeslagen, maar deze bewijsstukken konden niet worden verwijderd: {names} ({grund}).",
	"Die Buchung enthält ungespeicherte Änderungen. Beim Schließen gehen sie verloren.": "Deze boeking bevat niet-opgeslagen wijzigingen. Die gaan verloren als u haar sluit.",
	"Vorankündigung": "Vooraankondiging",
	"zurückgebucht": "gestorneerd",
	"einmalig": "eenmalig",
	"verschickt": "verzonden",
	"SEPA-Lastschriftmandate": "SEPA-incassomachtigingen",
	"Rein optionales Zusatzmodul für Vereine, die Mitgliedsbeiträge per Lastschrift einziehen. Ein Mandat gehört entweder zu einem Nextcloud-Konto oder zu einem frei benannten Zahler – letzteres etwa für Verbände, die nur Beitragsanteile von Untergliederungen einziehen und keine individuellen Mitglieder führen. Wer das nicht braucht, kann diesen Abschnitt einfach ignorieren.": "Een volledig optionele module voor verenigingen die contributie via incasso innen. Een machtiging hoort bij een Nextcloud-account of bij een vrij benoemde betaler – dat laatste bijvoorbeeld voor bonden die alleen contributieaandelen van hun afdelingen innen en geen individuele leden bijhouden. Hebt u dit niet nodig, negeer dit onderdeel dan gewoon.",
	"Grundeinstellungen": "Basisinstellingen",
	"Gläubiger-ID und einziehendes Konto werden für den SEPA-Sammeleinzug weiter unten gebraucht. Die Gläubiger-ID vergibt die Deutsche Bundesbank auf Antrag; am einziehenden Konto muss eine IBAN hinterlegt sein.": "De incassant-ID en de incassorekening zijn nodig voor de SEPA-incasso verderop. In Duitsland wordt de incassant-ID op aanvraag uitgegeven door de Bundesbank; voor de incassorekening moet een IBAN zijn vastgelegd.",
