	"Mandat nicht gefunden": "Machtiging niet gevonden",
	"Das sieht nicht nach einer SEPA-Gläubiger-ID aus (erwartet wird z. B. DE98ZZZ09999999999).": "Dat lijkt geen SEPA-incassant-ID te zijn (verwacht iets als DE98ZZZ09999999999).",
	"Das einziehende Konto muss ein Geldkonto sein.": "De incassorekening moet een geldrekening (bank/kas) zijn.",
	"Für das einziehende Konto ist keine IBAN hinterlegt. Bitte tragen Sie sie zuerst am Konto ein.": "Voor de incassorekening is geen IBAN vastgelegd. Vul die eerst bij de rekening in.",
	"Das gewählte einziehende Konto wurde nicht gefunden.": "De gekozen incassorekening is niet gevonden.",
	"Bitte entweder einen Nextcloud-Nutzer oder einen freien Zahlernamen angeben, nicht beides.": "Geef een Nextcloud-gebruiker of een vrije naam van de betaler op, niet beide.",
	"Bitte einen Nextcloud-Nutzer oder einen freien Zahlernamen angeben.": "Geef een Nextcloud-gebruiker of een vrije naam van de betaler op.",
