	"Bitte zuerst die SEPA-Gläubiger-ID in den Einstellungen hinterlegen.": "Vul eerst de SEPA-incassant-ID in bij de instellingen.",
	"Bitte zuerst den Vereinsnamen in den Einstellungen hinterlegen.": "Vul eerst de naam van de vereniging in bij de instellingen.",
	"Bitte zuerst das einziehende Konto in den Einstellungen hinterlegen.": "Kies eerst de incassorekening in de instellingen.",
	"Das eingestellte einziehende Konto wurde nicht gefunden.": "De ingestelde incassorekening is niet gevonden.",
	"Das einziehende Konto hat keine IBAN hinterlegt.": "Voor de incassorekening is geen IBAN vastgelegd.",
	"Mitgliedsbeitrag": "Contributie",
	"Die IBAN ist Pflicht.": "De IBAN is verplicht.",
	"Bevorstehender Lastschrifteinzug": "Aankomende incasso",
	"Bitte sorgen Sie für ausreichende Deckung Ihres Kontos. Bei Fragen wenden Sie sich an den Vorstand.": "Zorgt u ervoor dat er voldoende saldo op uw rekening staat. Hebt u vragen, neem dan contact op met het bestuur.",
	"Aufnehmen": "Lid toevoegen",
	"Bankverbindung": "Bankgegevens",
	"Beides ist einzeln möglich: ohne IBAN entsteht nur ein Beitrag (etwa für Überweiser), ohne Betrag nur ein Mandat.": "Elk deel is ook afzonderlijk mogelijk: zonder IBAN ontstaat alleen een contributie (voor leden die per overschrijving betalen), zonder bedrag alleen een machtiging.",
	"Das Konto \"%s %s\" ist in %d Buchungszeile%s verwendet und kann nicht gelöscht werden. ": "De rekening \"%s %s\" wordt gebruikt in %d boekingsregel(s) en kan niet worden verwijderd. ",
	"Das Konto \"%s\" ist in %s bebucht – %s dort abgeschlossen. %s lässt sich deshalb nicht mehr ändern: ": "De rekening \"%s\" heeft boekingen in %s – %s daar afgesloten. %s kan daarom niet meer worden gewijzigd: ",
	"Das Mandat wurde angelegt, der Beitrag nicht": "De machtiging is aangemaakt, de contributie niet",
	"Die Datei ist zu groß (höchstens %s MB).": "Het bestand is te groot (maximaal %s MB).",
	"Die E-Mail-Adresse ist ungültig: %s": "Ongeldig e-mailadres: %s",
	"Dieser Zahler steht schon in Zeile %s dieser Datei.": "Deze betaler staat al in regel %s van dit bestand.",
	"E-Mail": "E-mail",
	"Ein Mitglied besteht hier aus zwei Angaben: seiner Bankverbindung (dem SEPA-Mandat) und seinem Beitrag. Beides wird in einem Schritt angelegt. Eine eigene Mitgliederverwaltung führt die App bewusst nicht – wer keine Beiträge einzieht, braucht diesen Abschnitt nicht.": "Een lid bestaat hier uit twee gegevens: de bankgegevens (de SEPA-machtiging) en de contributie. Beide worden in één stap aangemaakt. De app houdt bewust geen ledenadministratie bij – als u geen contributie int, hebt u dit onderdeel niet nodig.",
	"Erste Fälligkeit": "Eerste vervaldatum",
	"Es gibt kein Nextcloud-Konto „%s\".": "Er bestaat geen Nextcloud-account “%s”.",
	"Es wurde keine Datei übergeben.": "Er is geen bestand meegestuurd.",
	"Für die erstmalige Aufnahme vieler Mitglieder: eine CSV-Datei mit den Spalten Name, E-Mail, IBAN, Mandat am, Betrag, Frequenz und Start. Die Reihenfolge und die Schreibweise der Überschriften sind egal, zusätzliche Spalten werden übergangen. Vor dem Anlegen sehen Sie zuerst, was entstehen würde.": "Om veel leden tegelijk toe te voegen: een CSV-bestand met de kolommen Naam, E-mail, IBAN, Machtigingsdatum, Bedrag, Frequentie en Start. Volgorde en schrijfwijze van de kopjes maken niet uit, extra kolommen worden genegeerd. Voordat er iets wordt aangemaakt, ziet u eerst wat er zou ontstaan.",
	"Für diese IBAN gibt es bereits ein aktives Mandat.": "Er bestaat al een actieve machtiging voor deze IBAN.",
	"Gläubiger-ID und einziehendes Konto werden für den Sammeleinzug gebraucht. Die Gläubiger-ID vergibt die Deutsche Bundesbank auf Antrag; am einziehenden Konto muss eine IBAN hinterlegt sein.": "De incassant-ID en de incassorekening zijn nodig voor de incasso. De Deutsche Bundesbank geeft de incassant-ID op aanvraag uit; voor de incassorekening moet een IBAN zijn vastgelegd.",
