	"Rein optionales Zusatzmodul für Vereine, die Mitgliedsbeiträge per Lastschrift einziehen. Wer das nicht braucht, kann diesen und die beiden folgenden Abschnitte einfach ignorieren.": "Een volledig optionele module voor verenigingen die contributie via incasso innen. Hebt u dit niet nodig, negeer dan gewoon dit onderdeel en de twee volgende.",
