	"Geschäftsjahr umbenannt": "Boekjaar hernoemd",
	"Geschäftsjahr umgestellt: {periods} Zeiträume, {moved} Buchungen neu zugeordnet.": "Boekjaar gewijzigd: {periods} perioden, {moved} boekingen opnieuw toegewezen.",
	"Geschäftsjahr umstellen": "Boekjaar wijzigen",
	"Geschäftsjahr wiedereröffnet": "Boekjaar heropend",
	"Geschäftsjahr wählen": "Boekjaar kiezen",
	"Geschäftsjahr-Regel": "Boekjaarregel",
	"Geschäftsjahr-Regel geändert": "Boekjaarregel gewijzigd",
	"Geschäftsjahr-Regel konnte nicht geladen werden": "De boekjaarregel kon niet worden geladen",
	"Geschäftsjahre zu ändern ist Verwaltern vorbehalten.": "Het wijzigen van boekjaren is voorbehouden aan beheerders.",
	"Grenze konnte nicht verschoben werden": "De grens kon niet worden verschoven",
	"Grenze von {label} verschoben.": "Grens van {label} verschoven.",
	"Im Kontoauszug (Reiter „Konten\") lassen sich Buchungen jetzt direkt bearbeiten – Knopf am Zeilenende, wie im Reiter „Buchungen\". Kein Notieren der Buchungsnummer und kein Wechsel der Ansicht mehr, nur um einen Text oder ein falsches Konto zu korrigieren. Belege sind dort ebenfalls einsehbar; das Umbuchen ist ins Menü hinter den drei Punkten gewandert.": "In het rekeningoverzicht (tabblad “Rekeningen”) kunnen boekingen nu direct worden bewerkt – met een knop aan het einde van de regel, net als in het tabblad “Boekingen”. U hoeft niet langer het boekingsnummer te noteren en van weergave te wisselen alleen om een omschrijving of een verkeerde rekening te corrigeren. Bewijsstukken kunnen daar ook worden bekeken; herboeken is verhuisd naar het menu achter de drie puntjes.",
	"Import blockiert: Der Übergang zum Geschäftsjahr %s stimmt nicht überein. Bitte die Beträge in den Dateien prüfen.": "Import geblokkeerd: de overgang naar boekjaar %s klopt niet. Controleer de bedragen in de bestanden.",
	"Kalenderjahr (1. Januar – 31. Dezember)": "Kalenderjaar (1 januari – 31 december)",
	"Kassenbericht %s": "Kasverslag %s",
	"Kassenbericht für das Geschäftsjahr %s": "Kasverslag over boekjaar %s",
	"Legt den Zeitraum nach dem bisher letzten an – nach der eingestellten Geschäftsjahr-Regel": "Maakt de periode na de laatste aan – volgens de ingestelde boekjaarregel",
	"Legt den Zeitraum nach dem bisher letzten an – nach der oben eingestellten Regel": "Maakt de periode na de laatste aan – volgens de hierboven ingestelde regel",
