	"Vorschau": "Voorbeeld",
	"Wählbar sind nur Längen, die 12 teilen. Eine andere Länge liefe Jahr für Jahr gegen den Kalender – nach einigen Zeiträumen begänne das Geschäftsjahr in einem anderen Monat als am Anfang.": "Alleen lengtes waardoor 12 deelbaar is, kunnen worden gekozen. Elke andere lengte zou jaar na jaar verschuiven ten opzichte van het kalenderjaar – na een paar perioden zou het boekjaar in een andere maand beginnen dan aan het begin.",
	"Zeitraum": "Periode",
