	"wird übernommen (keine Buchungen im Vorzeitraum vorhanden)": "wordt overgenomen (geen boekingen in de vorige periode)",
	"wird übersprungen – ⚠ Endstand des Vorzeitraums ist {prior} (Differenz {diff})": "wordt overgeslagen – ⚠ het eindsaldo van de vorige periode is {prior} (verschil {diff})",
	"wird übersprungen, stimmt mit dem Endstand des Vorzeitraums überein ✓": "wordt overgeslagen, komt overeen met het eindsaldo van de vorige periode ✓",
	"{label} ist abgeschlossen – die Grenze lässt sich nicht mehr verschieben.": "{label} is afgesloten – de grens kan niet meer worden verschoven.",
	"{n} überflüssige Eröffnungsbuchung(en) aus {label} werden beim Import entfernt (der Anfangsbestand kommt dann aus diesem früheren Zeitraum).": "{n} overbodige openingsboeking(en) uit {label} worden bij de import verwijderd (het beginsaldo komt dan uit deze eerdere periode).",
