	"⚠ Buchungsnummern {period} nicht lückenlos:": "⚠ Boekingsnummers voor {period} zijn niet doorlopend:",
	"⚠ {n} Buchung(en) liegen außerhalb des Geschäftsjahres {label} ({from} – {to}) und würden in der App einem anderen Zeitraum zugeordnet:": "⚠ {n} boeking(en) vallen buiten boekjaar {label} ({from} – {to}) en zouden in de app aan een andere periode worden toegewezen:",
	"⛔ Import blockiert, bis die Beträge am Zeitraumübergang übereinstimmen.": "⛔ Import geblokkeerd totdat de bedragen bij de periodeovergang overeenkomen.",
	"⛔ Umstellung nicht möglich: diese Zeiträume sind festgeschrieben und müssten zuerst wiedereröffnet werden.": "⛔ Wijziging niet mogelijk: deze perioden zijn vergrendeld en moeten eerst worden heropend.",
	"🔒 Das Geschäftsjahr {period} ist abgeschlossen – diese Buchung kann nur noch angesehen werden.": "🔒 Boekjaar {period} is afgesloten – deze boeking kan alleen nog worden bekeken.",
	"🔒 Das Geschäftsjahr {period} ist abgeschlossen – an dieser Buchung lässt sich nur noch der Kommentar ändern.": "🔒 Boekjaar {period} is afgesloten – alleen de opmerking bij deze boeking kan nog worden gewijzigd.",
