	"_%n{plus} Dokument_::_%n{plus} Dokumente_": [
		"%n{plus} document",
		"%n{plus} documenten"
	],
	"Diese Datei hängt bereits an der Buchung.": "Dit bestand is al aan de boeking gekoppeld.",
	"Keine weiteren Dateien im Wächter-Ordner.": "Geen verdere bestanden in de bewaakte map.",
	"Mein Beitrag": "Mijn contributie",
	"Kein Self-Service-Zugang.": "Geen toegang tot selfservice.",
	"Mitglied nicht gefunden": "Lid niet gevonden",
	"Meine Stammdaten": "Mijn gegevens",
	"Telefon": "Telefoon",
	"Adresse": "Adres",
	"Mitgliedsnummer": "Lidnummer",
	"Mitglied seit": "Lid sinds",
	"Mitglied bis": "Lid tot",
	"Mandat und Beitrag lassen sich hier bald selbst verwalten – bis dahin wendet euch für Änderungen an den Vorstand.": "Binnenkort kunt u uw machtiging en contributie hier zelf beheren – neem tot die tijd voor wijzigingen contact op met het bestuur.",
	"Deine Stammdaten konnten nicht geladen werden.": "Uw gegevens konden niet worden geladen.",
	"Self-Service „Mein Beitrag\" für verknüpfte Nextcloud-Konten freischalten": "Selfservice “Mijn contributie” inschakelen voor gekoppelde Nextcloud-accounts",
	"Betrifft nur Mitglieder, deren Nextcloud-Konto in der Mitgliederakte verknüpft ist – sie sehen dann ihre eigenen Stammdaten, unabhängig von einer Buchhaltungsrolle.": "Geldt alleen voor leden van wie het Nextcloud-account in het ledendossier is gekoppeld – zij zien dan hun eigen gegevens, ongeacht een eventuele rol in de boekhouding.",
	"Änderungen an meinem Beitrag (Mandat, Beitrag, Stammdaten)": "Wijzigingen in mijn contributie (machtiging, contributie, persoonsgegevens)",
	"Überweisung": "Overschrijving",
	"Entwurf": "Concept",
	"ausgesetzt": "opgeschort",
	"ab {datum}": "vanaf {datum}",
	"beendet {datum}": "beëindigd {datum}",
	"alle {monate} Monate": "elke {monate} maanden",
	"Beitragsgruppen": "Contributiegroepen",
	"Reiter „Beiträge\" → Mitglieder: je Mitglied ein SEPA-Mandat (IBAN, Unterschriftsdatum) und/oder eine Zuweisung zu einer Beitragsgruppe (Monatsbeitrag, Turnus). Der Knopf „Mitglied\" nimmt ein Mitglied samt optionalem Mandat und Beitrag in einem Dialog auf. Aus den Zuweisungen entstehen die Forderungen.": "Tabblad “Contributies” → Leden: per lid één SEPA-machtiging (IBAN, datum van ondertekening) en/of één toewijzing aan een contributiegroep (maandcontributie, interval). De knop “Lid” legt een lid samen met een optionele machtiging en contributie in één dialoogvenster vast. Uit de toewijzingen ontstaan de vorderingen.",
	"Reiter „Beiträge\" → Einzug: Vorschau des Einzugstermins prüfen, den Lauf freigeben (dabei entsteht die SEPA-Datei), die Datei bei der Hausbank einreichen und die Einreichung hier bestätigen. Vor dem ersten Einzug mit dem Prüftool der Bank testen.": "Tabblad “Contributies” → Incasso: controleer het voorbeeld van de incassodatum, geef de run vrij (daarbij ontstaat het SEPA-bestand), lever het bestand in bij uw bank en bevestig de aanlevering hier. Test het met de validatietool van uw bank vóór de eerste echte incasso.",
	"Die Vorabinfo über Betrag und Termin (Standard: 14 Tage vor dem Einzug) verschickt die App automatisch an Mitglieder mit hinterlegter E-Mail-Adresse.": "De app verstuurt de vooraankondiging over bedrag en datum (standaard: 14 dagen vóór de incasso) automatisch naar leden van wie een e-mailadres is vastgelegd.",
	"Einzug → Bankabgleich: Sammelgutschriften, Rücklastschriften und Zahlungseingänge aus dem Kontoauszugs-Import prüfen und verbuchen.": "Incasso → Bankafstemming: verzamelbijschrijvingen, gestorneerde incasso's en ontvangen betalingen uit de import van bankafschriften controleren en verwerken.",
	"_+ %n weitere Zuweisung_::_+ %n weitere Zuweisungen_": [
		"+ nog %n toewijzing",
		"+ nog %n toewijzingen"
	],
	"Das Konto \"%s %s\" ist in %d Buchungszeile%s verwendet und kann nicht gelöscht werden. Setzen Sie es stattdessen auf „inaktiv\" – dann taucht es nicht mehr in den Auswahllisten auf, die bisherigen Buchungen bleiben aber erhalten.": "De rekening \"%s %s\" wordt gebruikt in %d boekingsregel(s) en kan niet worden verwijderd. Zet de rekening in plaats daarvan op “inactief” – dan verdwijnt ze uit de keuzelijsten, terwijl de bestaande boekingen behouden blijven.",
	"Frieren Sie den aktuellen Finanzplan als benannten, datierten Stand ein (z.B. den in der Mitgliederversammlung beschlossenen Haushalt). Spätere Planänderungen lassen den Stand unberührt.": "Leg de huidige begroting vast als benoemde, gedateerde versie (bijv. de begroting die door de algemene ledenvergadering is vastgesteld). Latere wijzigingen in de begroting laten deze versie ongemoeid.",
	"Importieren Sie Kontoumsätze oder legen Sie manuell Buchungssätze an.": "Importeer banktransacties of maak handmatig journaalboekingen aan.",
	"Keine Daten. Importieren oder erfassen Sie zuerst Buchungen.": "Geen gegevens. Importeer of registreer eerst boekingen.",
	"Legen Sie mit ‛Neue Buchung' einen ersten Buchungssatz an.": "Maak met “Nieuwe boeking” uw eerste boeking aan.",
	"Legen Sie oben eine Regel an – oder erzeugen Sie sie im Journal direkt aus einer Bankbuchung.": "Maak hierboven een regel aan – of genereer er direct een vanuit een banktransactie in het journaal.",
	"Legen Sie oben einen neuen offenen Posten an, z. B. einen unbezahlten Mitgliedsbeitrag.": "Maak hierboven een nieuwe openstaande post aan, bijv. een onbetaalde contributie.",
	"Rücklagen sind Eigenkapital-Konten mit festgelegter Rücklagen-Art (§ 62 AO). Zuweisungen erfolgen als normale Buchung (Experten-Modus im Buchungsdialog, Eigenkapital-zu-Eigenkapital-Umbuchung) – hier sehen Sie nur den aktuellen Stand je Art.": "Reserves zijn eigenvermogensrekeningen met een vastgelegd soort reserve (§ 62 AO, Duitse belastingwet). Toevoegingen gebeuren als normale boeking (expertmodus in het boekingsvenster, overboeking van eigen vermogen naar eigen vermogen) – hier ziet u alleen het actuele saldo per soort.",
	"Sie haben keine Berechtigung für die Vereinsbuchhaltung. Bitte wenden Sie sich an eine Verwalterin oder einen Verwalter.": "U hebt geen rechten voor de verenigingsboekhouding. Neem contact op met een beheerder.",
	"Womit möchten Sie starten? Das lässt sich jederzeit später ändern.": "Waarmee wilt u beginnen? U kunt dit later altijd nog wijzigen.",
	"Wählen Sie die Kategorie (z. B. „Mitgliedsbeiträge\") und das Geldkonto – die App bucht Soll/Haben automatisch richtig. Schritt 2 von 3.": "Kies de categorie (bijv. “contributies”) en de geldrekening – de app boekt debet/credit automatisch correct. Stap 2 van 3.",
	"Wählen Sie zuerst, ob Geld reinkommt oder rausgeht – Schritt 1 von 3.": "Kies eerst of er geld binnenkomt of uitgaat – stap 1 van 3.",
	"Mandats-Rechtstext": "Juridische tekst van de machtiging",
