	"Störfälle": "Afwijkingen",
	"(betrifft das Mitglied)": "(betreft het lid)",
	"Mitglieder-Akte öffnen": "Ledendossier openen",
	"Störfälle blockieren nichts und müssen nicht quittiert werden – sie verschwinden von selbst, sobald ihre Ursache behoben ist.": "Afwijkingen blokkeren niets en hoeven niet te worden bevestigd – ze verdwijnen vanzelf zodra de oorzaak is verholpen.",
	"Im Lauf zum Einzug am {datum} ({status}).": "In de run voor de incasso op {datum} ({status}).",
	"Rücklastschrift vom {datum}.": "Gestorneerde incasso van {datum}.",
	"Die Forderung wird nicht erneut eingezogen (kein Wiedereinzug). Sie bleibt offen, bis sie bezahlt, erlassen oder gestundet wird; die Zahlungsaufforderung geht je nach Grund automatisch an das Mitglied.": "De vordering wordt niet opnieuw geïncasseerd (geen herincasso). Ze blijft openstaan totdat ze betaald, kwijtgescholden of uitgesteld wordt; het betalingsverzoek gaat, afhankelijk van de reden, automatisch naar het lid.",
	"Mahnstand": "Aanmaningsstatus",
	"Gestundet bis {datum}: Zahlungserinnerung, Mahnung und Eskalation pausieren bis dahin; danach läuft die Mahnuhr von der zuletzt erreichten Stufe weiter.": "Uitstel tot {datum}: betalingsherinnering, aanmaning en escalatie zijn tot dan gepauzeerd; daarna loopt de aanmaningsprocedure verder vanaf het laatst bereikte niveau.",
	"Bisher wurde nichts versandt, und es ist auch nichts angekündigt. Bei Lastschrift-Forderungen beginnt die Mahnreihe erst nach einer Rücklastschrift oder einem Widerruf des Mandats; Überweiser-Forderungen erhalten die Zahlungsaufforderung kurz vor der Fälligkeit.": "Tot nu toe is er niets verstuurd en er is ook niets aangekondigd. Bij vorderingen per incasso begint de aanmaningsreeks pas na een gestorneerde incasso of een intrekking van de machtiging; vorderingen per overschrijving krijgen het betalingsverzoek kort voor de vervaldatum.",
	"Mahnabstand: {tage} Tage (Einstellung der Verwaltung).": "Aanmaningsinterval: {tage} dagen (instelling van de beheerder).",
	"Stundung": "Uitstel",
	"Gestundet bis {datum}.": "Uitstel tot {datum}.",
	"Die Stundung bis {datum} ist abgelaufen.": "Het uitstel tot {datum} is verlopen.",
	"Erledigungsvermerk": "Afhandelingsnotitie",
	"Erlassen": "Kwijtgescholden",
