	"Stundung gesetzt.": "Uitstel ingesteld.",
	"Forderung storniert.": "Vordering geannuleerd.",
	"Der Vermerk konnte nicht gespeichert werden.": "De notitie kon niet worden opgeslagen.",
	"Der Erlass konnte nicht gespeichert werden.": "De kwijtschelding kon niet worden opgeslagen.",
	"Die Stundung konnte nicht gespeichert werden.": "Het uitstel kon niet worden opgeslagen.",
	"Die Forderung konnte nicht storniert werden.": "De vordering kon niet worden geannuleerd.",
	"Die Stundung endet sofort. Das Mahnwesen läuft von der zuletzt erreichten Stufe weiter, der nächste Schritt kann damit schon am nächsten Tag anstehen.": "Het uitstel eindigt onmiddellijk. De aanmaningsprocedure loopt verder vanaf het laatst bereikte niveau, dus de volgende stap kan al de volgende dag aan de orde zijn.",
