	"Eine Erhöhung der Untergrenze läuft über die eigene Funktion „Untergrenze anheben\" in der Gruppenliste – hier lässt sie sich nur absenken.": "De ondergrens verhogen gaat via de aparte functie “Ondergrens verhogen” in de groepenlijst – hier kan deze alleen worden verlaagd.",
