	"Einstellungen konnten nicht gespeichert werden": "Instellingen konden niet worden opgeslagen",
	"Ansicht im Einzug": "Weergave in Incasso",
	"Der Einzug konnte nicht geladen werden.": "De incasso kon niet worden geladen.",
	"Läufe": "Runs",
