	"Sperren": "Blokkeren",
	"Entsperren": "Deblokkeren",
	"Ohne Mailadresse beim Mitglied lässt sich kein Einmal-Link verschicken.": "Zonder e-mailadres bij het lid kan geen eenmalige link worden verstuurd.",
	"Mandat aktivieren": "Machtiging activeren",
	"Das Unterschriftsdatum liegt mehr als 36 Monate zurück – das Mandat würde nach der Aktivierung sofort verfallen. Bitte prüfen Sie das Datum.": "De ondertekeningsdatum ligt meer dan 36 maanden terug – de machtiging zou direct na activering vervallen. Controleer de datum.",
	"Grund der Sperre (Pflicht)": "Reden voor de blokkering (verplicht)",
	"z. B. Rückfrage beim Mitglied wegen Kontowechsel": "bijv. navraag bij het lid over een rekeningwijziging",
	"Ein gesperrtes Mandat wird nicht eingezogen; offene Forderungen bleiben offen.": "Een geblokkeerde machtiging wordt niet geïncasseerd; openstaande vorderingen blijven openstaan.",
	"Mandat sperren": "Machtiging blokkeren",
