	"Ohne Unterschriftsdatum bleibt das Mandat ein Entwurf – erst das Datum aktiviert es sofort.": "Zonder ondertekeningsdatum blijft de machtiging een concept – pas de datum activeert haar direct.",
	"– keine Zuweisung –": "– geen toewijzing –",
	"Ohne Mailadresse ist keine Vorabinformation und kein Lastschrifteinzug möglich – Zahlungsart wird auf Überweisung gesetzt.": "Zonder e-mailadres is geen vooraankondiging en geen incasso mogelijk – de betaalwijze wordt ingesteld op overschrijving.",
	"Erste Periode: {from} bis {to} ({months}) · Einzugsbetrag {amount} · voraussichtlicher Einzugstermin {due}": "Eerste periode: {from} tot {to} ({months}) · incassobedrag {amount} · verwachte incassodatum {due}",
	"Diese Mitgliedsakte wurde am {datum} DSGVO-anonymisiert. Name, Kontaktdaten und personenbezogene Freitexte sind unwiderruflich entfernt; Stammdaten können nicht mehr bearbeitet werden.": "Dit ledendossier is op {datum} in het kader van de AVG geanonimiseerd. Naam, contactgegevens en persoonlijke vrije tekst zijn onherroepelijk verwijderd; stamgegevens kunnen niet meer worden bewerkt.",
	"Nextcloud-Konto": "Nextcloud-account",
	"Ohne Mailadresse gibt es keinen Vorschlag – erst speichern, dann verknüpfen.": "Zonder e-mailadres is er geen suggestie – eerst opslaan, dan koppelen.",
