	"Druckfertige Auskunft über alle gespeicherten Daten – kein strukturierter Export nach Art. 20 DSGVO.": "Afdrukklaar overzicht van alle opgeslagen gegevens – geen gestructureerde export volgens art. 20 AVG.",
	"Datenübersicht öffnen": "Gegevensoverzicht openen",
	"Anonymisierung (Art. 17 DSGVO)": "Anonimisering (art. 17 AVG)",
	"Anonymisierungsreif: die letzte zugehörige Buchung liegt mehr als 10 Jahre zurück – die Bestätigung ist irreversibel.": "Klaar voor anonimisering: de laatste bijbehorende boeking ligt meer dan 10 jaar terug – de bevestiging is onomkeerbaar.",
	"Noch nicht anonymisierungsreif (frühestens ab {datum} – 10 Jahre nach der letzten zugehörigen Buchung).": "Nog niet klaar voor anonimisering (op zijn vroegst vanaf {datum} – 10 jaar na de laatste bijbehorende boeking).",
