	"Name, Kontaktdaten, Bankverbindungen und personenbezogene Freitexte von „{name}\" unwiderruflich schwärzen? Das lässt sich nicht rückgängig machen.": "Naam, contactgegevens, bankgegevens en persoonlijke vrije tekst van “{name}” onherroepelijk onleesbaar maken? Dit kan niet ongedaan worden gemaakt.",
