	"Verknüpfen fehlgeschlagen": "Koppelen mislukt",
	"Die Verknüpfung mit dem Nextcloud-Konto lösen? Das Mitglied und seine Historie bleiben bestehen.": "Koppeling met het Nextcloud-account opheffen? Het lid en de geschiedenis blijven bestaan.",
	"Lösen": "Ontkoppelen",
	"Verknüpfung gelöst.": "Koppeling opgeheven.",
	"Lösen fehlgeschlagen": "Ontkoppelen mislukt",
