	"Mitglied „{name}\" endgültig löschen?": "Lid “{name}” definitief verwijderen?",
	"Mitglied gelöscht.": "Lid verwijderd.",
	"Zeilen mit Start-Datum, aber ohne eigenen Betrag, bekommen den üblichen Betrag ihrer Beitragsgruppe – die Betrag-Spalte kann bei einheitlichen Sätzen also leer bleiben.": "Regels met een startdatum maar zonder eigen bedrag krijgen het gebruikelijke bedrag van hun contributiegroep – bij uniforme tarieven kan de kolom met het bedrag dus leeg blijven.",
	"{ok} von {total} Zeilen sind in Ordnung: {mandate} und {beitraege} würden angelegt. {uebersprungen} bereits vorhandene oder doppelte Zeilen werden übersprungen, {fehler} sind fehlerhaft.": "{ok} van {total} regels zijn in orde: {mandate} en {beitraege} zouden worden aangemaakt. {uebersprungen} bestaande of dubbele regels worden overgeslagen, {fehler} zijn foutief.",
	"{ok} von {total} Zeilen übernommen: {mandate} und {beitraege} angelegt. {uebersprungen} bereits vorhandene oder doppelte Zeilen wurden übersprungen, {fehler} waren fehlerhaft.": "{ok} van {total} regels geïmporteerd: {mandate} en {beitraege} aangemaakt. {uebersprungen} bestaande of dubbele regels zijn overgeslagen, {fehler} waren foutief.",
