	"{n} von {gesamt} beurteilt": "{n} van {gesamt} beoordeeld",
	"Keine Zeile ist einem Posten zugeordnet – es gibt nichts zu verbuchen. Ändern Sie ein Urteil, oder buchen Sie den Umsatz unter Buchungen von Hand.": "Geen enkele regel is aan een post toegewezen – er valt niets te boeken. Wijzig een beoordeling of boek de transactie handmatig onder Boekingen.",
	"Verbuchen ist erst möglich, wenn alle {gesamt} Zeilen beurteilt sind – noch {offen} offen.": "Boeken is pas mogelijk als alle {gesamt} regels zijn beoordeeld – nog {offen} open.",
	"Einzugsgutschrift": "Incassobijschrijving",
	"Gutschrift und Rücklastschrift": "Bijschrijving en gestorneerde incasso",
	"wartet auf Urteil": "wacht op beoordeling",
	"bereit zum Verbuchen": "klaar om te boeken",
	"ohne Zuordnung beurteilt": "beoordeeld zonder toewijzing",
	"noch nicht beurteilt": "nog niet beoordeeld",
	"zugeordnet": "toegewezen",
	"abgelehnt": "afgewezen",
	"nicht zuordenbar": "niet toe te wijzen",
