	"Gleicher Betrag und gleiche Zahler-IBAN": "Zelfde bedrag en zelfde IBAN van betaler",
	"Mangels Kontodeckung zurückgegeben": "Teruggeboekt wegens onvoldoende saldo",
	"Konto nicht nutzbar (z. B. aufgelöst, gesperrt oder IBAN ungültig)": "Rekening niet bruikbaar (bijv. opgeheven, geblokkeerd of ongeldige IBAN)",
	"Vom Zahlungspflichtigen widersprochen oder ohne gültiges Mandat": "Door de betaler betwist of zonder geldige machtiging",
	"Zahlungspflichtiger verstorben": "Betaler overleden",
	"Technischer oder formaler Fehler (z. B. Doppeleinreichung oder Datenfehler)": "Technische of formele fout (bijv. dubbele aanlevering of gegevensfout)",
	"Grund unbekannt oder von der Bank nicht übermittelt": "Reden onbekend of niet door de bank doorgegeven",
	"Die Forderung wird wieder offen. Sie wird nicht erneut per Lastschrift eingezogen.": "De vordering komt weer open te staan. Ze wordt niet opnieuw via incasso geïnd.",
	"Das Mandat wird gesperrt: Es wird nicht mehr eingezogen, bis Sie es in der Mitglieder-Akte geklärt und entsperrt haben.": "De machtiging wordt geblokkeerd: er wordt niet meer geïncasseerd totdat u de zaak in het ledendossier hebt opgehelderd en de machtiging hebt gedeblokkeerd.",
	"Das Mitglied erhält sofort eine Zahlungsaufforderung per E-Mail (sofern eine E-Mail-Adresse hinterlegt ist).": "Het lid ontvangt direct een betalingsverzoek per e-mail (als er een e-mailadres is vastgelegd).",
	"Die Bankgebühr von {betrag} wird dem Mitglied als eigene Gebühren-Forderung weiterbelastet.": "De bankkosten van {betrag} worden als aparte vordering voor kosten doorberekend aan het lid.",
	"Erlös": "Opbrengst",
	"Erlös zurück": "Opbrengst terug",
	"Der Bankumsatz vom {datum} liegt in einem abgeschlossenen Geschäftsjahr und kann deshalb nicht verbucht werden. Ein Verwalter kann das Geschäftsjahr in den Nextcloud-Einstellungen unter Vereinsbuchhaltung → Geschäftsjahr wiedereröffnen.": "De banktransactie van {datum} valt in een afgesloten boekjaar en kan daarom niet worden geboekt. Een beheerder kan het boekjaar heropenen in de Nextcloud-instellingen onder Vereinsbuchhaltung → Boekjaar.",
	"Dieser Bankumsatz ist bereits gebucht. Laden Sie die Liste neu: Möglicherweise hat jemand anderes ihn gerade verbucht.": "Deze banktransactie is al geboekt. Laad de lijst opnieuw: mogelijk heeft iemand anders haar zojuist geboekt.",
	"Der Bankumsatz liegt in einem abgeschlossenen Geschäftsjahr und kann deshalb nicht verbucht werden. Ein Verwalter kann das Geschäftsjahr in den Nextcloud-Einstellungen unter Vereinsbuchhaltung → Geschäftsjahr wiedereröffnen.": "De banktransactie valt in een afgesloten boekjaar en kan daarom niet worden geboekt. Een beheerder kan het boekjaar heropenen in de Nextcloud-instellingen onder Vereinsbuchhaltung → Boekjaar.",
	"Dafür fehlt Ihnen die Berechtigung: Urteile und Verbuchungen sind ab der Rolle Buchhalter möglich.": "U hebt hiervoor geen rechten: beoordelingen en boekingen vereisen de rol boekhouder.",
	"Der Eintrag wurde nicht gefunden – möglicherweise hat ihn jemand anderes inzwischen geändert. Laden Sie die Liste neu.": "De vermelding is niet gevonden – mogelijk heeft iemand anders haar inmiddels gewijzigd. Laad de lijst opnieuw.",
