	"Für die XML-Ablage muss im Abschnitt „Belege\" ein Nextcloud-Nutzer gewählt und gespeichert sein – die Dateien liegen im Home dieses Nutzers.": "Voor de XML-opslag moet in de sectie “Bewijsstukken” een Nextcloud-gebruiker gekozen en opgeslagen zijn – de bestanden worden in de thuismap van die gebruiker opgeslagen.",
