	"Kein Nachweis-Dokument hinterlegt": "Geen bewijsdocument vastgelegd",
	"Für Sie liegt aktuell kein elektronischer Mandats-Entwurf vor, der eine Bestätigung braucht.": "Er staat momenteel geen elektronische concept-machtiging voor u klaar die een bevestiging nodig heeft.",
	"Für die Weiterbelastung der Rücklastschriftgebühren muss zuerst ein Konto für Rücklastschriftgebühren gewählt sein.": "Om stornokosten door te berekenen, moet eerst een rekening voor stornokosten worden gekozen.",
	"Ungültiges Mandatsreferenz-Präfix.": "Ongeldig voorvoegsel voor het machtigingskenmerk.",
	"Nextcloud-Konto wurde gelöscht, die Mailadresse wurde übernommen – bitte prüfen.": "Het Nextcloud-account is verwijderd en het e-mailadres is overgenomen – controleer dit.",
	"Das Konto \"%s\" ist in %s bebucht – %s dort abgeschlossen. %s lässt sich deshalb nicht mehr ändern: die Auswertungen dieses Zeitraums würden sich nachträglich verschieben. Wer die Änderung braucht, eröffnet den Zeitraum wieder und schließt ihn danach erneut ab.": "Op de rekening “%s” is geboekt in %s – daar afgesloten: %s. %s kan daarom niet meer worden gewijzigd: de analyses van die periode zouden achteraf verschuiven. Als u de wijziging nodig hebt, heropen dan de periode en sluit haar daarna opnieuw af.",
	"anonymisierungsreif, die letzte zugehörige Buchung liegt mehr als 10 Jahre zurück. Die Anonymisierung muss ein Buchhalter bestätigen, sie geschieht nie von selbst.": "klaar voor anonimisering, de laatste bijbehorende boeking ligt meer dan 10 jaar terug. Een boekhouder moet de anonimisering bevestigen, ze gebeurt nooit vanzelf.",
	"Ende der Zuweisung darf nicht vor ihrem Beginn liegen.": "Het einde van de toewijzing mag niet vóór het begin liggen.",
	"Dieser Turnus ist für die gewählte Beitragsgruppe nicht erlaubt.": "Deze frequentie is niet toegestaan voor de gekozen contributiegroep.",
	"Unbekannte Zahlungsart.": "Onbekende betaalwijze.",
