	"Nur offene Forderungen können erledigt werden.": "Alleen openstaande vorderingen kunnen worden afgehandeld.",
	"Ein Erlass braucht eine Begründung.": "Voor een kwijtschelding is een reden nodig.",
	"Nur offene Forderungen können storniert werden.": "Alleen openstaande vorderingen kunnen worden geannuleerd.",
	"Diese Forderung steckt in einem eingereichten Lauf und lässt sich nicht mehr stornieren. Ist sie berechtigt, aber nicht mehr zu erwarten, vermerken Sie einen Erlass.": "Deze vordering zit in een aangeleverde run en kan niet meer worden geannuleerd. Als ze terecht is maar niet meer te verwachten valt, leg dan een kwijtschelding vast.",
	"Diese Forderung steckt in einem freigegebenen Lauf, dessen Datei sie bereits enthält. Verwerfen Sie zuerst den Lauf; danach lässt sich die Forderung stornieren.": "Deze vordering zit in een vrijgegeven run waarvan het bestand haar al bevat. Verwerp eerst de run; daarna kan de vordering worden geannuleerd.",
	"Ein Storno braucht eine Begründung.": "Voor een annulering is een reden nodig.",
	"Nur offene Forderungen können gestundet werden.": "Alleen openstaande vorderingen kunnen worden uitgesteld.",
	"Es gibt bereits eine aktive Stundung für diese Forderung.": "Er is al een actief uitstel van betaling voor deze vordering.",
	"Das Stundungsdatum darf nicht in der Vergangenheit liegen.": "De datum van het uitstel mag niet in het verleden liggen.",
	"Eine Stundung braucht eine Begründung.": "Voor uitstel van betaling is een reden nodig.",
