	"Eine Erhöhung der Untergrenze läuft über die eigene Vorschau-Funktion, nicht über das normale Speichern.": "Het verhogen van de ondergrens verloopt via een eigen voorbeeldfunctie, niet via het normale opslaan.",
	"Diese Beitragsgruppe hat noch Zuweisungen und kann nicht gelöscht werden. Stattdessen deaktivieren.": "Deze contributiegroep heeft nog toewijzingen en kan niet worden verwijderd. Deactiveer haar in plaats daarvan.",
