	"Keine bis zum %s fälligen offenen Posten mit einzugsfähigem Mandat gefunden.": "Geen openstaande posten gevonden die uiterlijk %s verschuldigd zijn en een incasseerbare machtiging hebben.",
	"Für das Verwerfen eines Laufs ist eine Begründung Pflicht.": "Voor het verwerpen van een run is een reden verplicht.",
	"Nur ein freigegebener, noch nicht eingereichter Lauf lässt sich als eingereicht markieren.": "Alleen een vrijgegeven run die nog niet is aangeleverd, kan als aangeleverd worden gemarkeerd.",
