	"Einreichung überfällig: Lauf vom %s ist freigegeben, aber noch nicht bei der Bank eingereicht.": "Aanlevering te laat: de run van %s is vrijgegeven, maar nog niet bij de bank aangeleverd.",
	"Für die XML-Ablage ist noch kein Nextcloud-Nutzer eingerichtet (Einstellungen → Belegablage).": "Er is nog geen Nextcloud-gebruiker ingesteld voor de XML-opslag (Instellingen → Opslag bewijsstukken).",
