	"Dieser Einzugstermin würde den Termin der vorherigen Periode überholen.": "Deze incassodatum zou de datum van de vorige periode inhalen.",
	"Das SEPA-Mandat wurde widerrufen, ein Einzug per Lastschrift ist für diese Position nicht mehr möglich.": "De SEPA-machtiging is ingetrokken; incasso is voor deze post niet meer mogelijk.",
	"Für diese Position liegt uns bislang kein Zahlungseingang vor.": "Wij hebben voor deze post tot nu toe geen betaling ontvangen.",
	"Für diese Position liegt uns weiterhin kein Zahlungseingang vor.": "Wij hebben voor deze post nog steeds geen betaling ontvangen.",
	"Trotz Erinnerung liegt für diese Position noch kein Zahlungseingang vor. Bitte gleichen Sie den Betrag zeitnah aus, andernfalls legen wir den Vorgang dem Vorstand vor.": "Ondanks de herinnering is voor deze post nog geen betaling ontvangen. Wij verzoeken u het bedrag zo snel mogelijk te voldoen, anders leggen wij de zaak voor aan het bestuur.",
	"Ihre Organisation": "Uw organisatie",
	"Sollte der Betrag weiterhin nicht eingehen, legen wir den Vorgang dem Vorstand vor.": "Als het bedrag nog steeds niet binnenkomt, leggen wij de zaak voor aan het bestuur.",
	"Bitte überweisen Sie jede Position einzeln mit dem jeweils genannten Betrag – für jede Position liegt ein GiroCode zum Scannen mit Ihrer Banking-App als Bild bei (die Datei „GiroCode-Position-1.png“ gehört zu Position 1 und so weiter).": "Wij verzoeken u elke post afzonderlijk over te maken met het vermelde bedrag – voor elke post is een GiroCode als afbeelding bijgevoegd die u met uw bankapp kunt scannen (het bestand \"GiroCode-Position-1.png\" hoort bij post 1, enzovoort).",
