	"Diese Bestätigung ist ein informeller Beleg über gezahlte Mitgliedsbeiträge. Sie ist KEINE amtliche Zuwendungsbestätigung nach § 10b EStG und hat keine steuerliche Wirkung.": "Deze bevestiging is een informeel bewijs van betaalde contributies. Het is GEEN officiële giftbevestiging (Zuwendungsbestätigung) volgens § 10b EStG en heeft geen fiscale werking.",
