	"Stammdaten": "Stamgegevens",
	"Diese Mitgliedsakte wurde am %s im Rahmen der gesetzlich vorgesehenen DSGVO-Anonymisierung geschwärzt. Name, Kontaktdaten, Bankverbindungen und personenbezogene Freitexte sind unwiderruflich entfernt; nur strukturierte Angaben (Beträge, Daten, Status) bleiben aus buchhalterischen Gründen erhalten.": "Dit ledendossier is op %s onleesbaar gemaakt in het kader van de wettelijk voorgeschreven anonimisering volgens de AVG. Naam, contactgegevens, bankgegevens en persoonlijke vrije tekst zijn onherroepelijk verwijderd; alleen gestructureerde informatie (bedragen, data, status) blijft om boekhoudkundige redenen bewaard.",
