	"Elektronischer Erteilungslink für %1$s (Mandat %2$s) wartet seit %3$d Tagen auf Zustimmung.": "De elektronische link voor het verlenen van de machtiging voor %1$s (machtiging %2$s) wacht al %3$d dagen op instemming.",
	"Für die Mandats-Nachweisablage ist noch kein Nextcloud-Nutzer eingerichtet (Einstellungen → Belegablage).": "Er is nog geen Nextcloud-gebruiker ingesteld voor de opslag van machtigingsbewijzen (Instellingen → Opslag bewijsstukken).",
