	"Nur ein Mandat im Entwurf lässt sich verwerfen – ein aktives oder ausgesetztes Mandat wird widerrufen.": "Alleen een machtiging in concept kan worden verworpen – een actieve of opgeschorte machtiging wordt ingetrokken.",
	"Nur ein Mandat im Entwurf lässt sich auf diesem Weg korrigieren – bei einem aktiven Mandat ändert ein Amendment die Bankverbindung.": "Alleen een machtiging in concept kan op deze manier worden gecorrigeerd – bij een actieve machtiging wijzigt een amendement de bankgegevens.",
