	"Mindestens eine Zeile würde ein SEPA-Mandat anlegen. Bitte bestätigen Sie zuerst, dass die unterschriebenen Mandate vorliegen.": "Minstens één regel zou een SEPA-machtiging aanmaken. Bevestig eerst dat de ondertekende machtigingen aanwezig zijn.",
