	"Beitragsforderungen werden im Einzug-Reiter bearbeitet. Eine erledigte oder stornierte Forderung lässt sich nicht wieder öffnen; nur eine Rücklastschrift öffnet sie wieder.": "Contributievorderingen worden bewerkt in het tabblad Incasso. Een afgehandelde of geannuleerde vordering kan niet worden heropend; alleen een gestorneerde incasso heropent deze.",
