	"Sie bleiben als Nachweis erhalten. Für Datenschutzfälle gibt es die Anonymisierung.": "Deze blijven als bewijs bewaard. Voor privacygevallen is er de anonimisering.",
	"Beitrag ändern": "Contributie wijzigen",
	"Gezahlt werden darf beliebig mehr als die Untergrenze, etwa wenn das Mitglied ausnahmsweise mehr geben möchte.": "Er mag willekeurig meer dan de ondergrens worden betaald, bijvoorbeeld als het lid bij uitzondering meer wil geven.",
