	"Untergrenze der gewählten Gruppe: {min}. Beim Wechsel ist deren Standardbeitrag eingetragen; Sie können ihn anpassen.": "Ondergrens van de gekozen groep: {min}. Bij het wisselen wordt de standaardcontributie van die groep ingevuld; u kunt deze aanpassen.",
