	"Die Zuweisung hat noch nicht begonnen. Sie wird zurückgenommen und nie wirksam; es entstehen keine Forderungen daraus.": "De toewijzing is nog niet begonnen. Ze wordt teruggenomen en treedt nooit in werking; er ontstaan geen vorderingen uit.",
