	"Dafür wird eine E-Mail-Adresse gebraucht.": "Hiervoor is een e-mailadres nodig.",
	"Unabhängig davon, ob das Mitglied ein Nextcloud-Konto bekommt. Die Vorlage steht in den Einstellungen unter „Willkommens-Mail“.": "Ongeacht of het lid een Nextcloud-account krijgt. Het sjabloon staat in de instellingen onder “Welkomstmail”.",
