	"Sprache": "Taal",
	"Das Mitglied meldet sich mit diesem Passwort an.": "Het lid meldt zich met dit wachtwoord aan.",
	"Ohne Passwort bekommt das Mitglied von Nextcloud eine Einladung per Mail – mit einem Link, um das Passwort selbst zu setzen.": "Zonder wachtwoord krijgt het lid van Nextcloud een uitnodiging per e-mail – met een link om zelf het wachtwoord in te stellen.",
	"Ohne Passwort verschickt Nextcloud keine Einladung (die Instanz ist so eingestellt); das Mitglied kann sich erst nach dem Setzen eines Passworts anmelden.": "Zonder wachtwoord verstuurt Nextcloud geen uitnodiging (de instantie is zo ingesteld); het lid kan zich pas aanmelden nadat er een wachtwoord is ingesteld.",
	"unbegrenzt": "onbeperkt",
	"Standard ({quota})": "Standaard ({quota})",
	"Unbegrenzt": "Onbeperkt",
	"Standard der Instanz": "Standaard van de instantie",
	"Diese Mail können Sie beim Aufnehmen eines Mitglieds und aus der Akte an die E-Mail-Adresse des Mitglieds schicken – unabhängig davon, ob es ein Nextcloud-Konto hat. Beim Versenden lässt sich der Text für den Einzelfall anpassen.": "Deze e-mail kunt u bij het opnemen van een lid en vanuit het dossier naar het e-mailadres van het lid sturen – ongeacht of het een Nextcloud-account heeft. Bij het verzenden kan de tekst voor het individuele geval worden aangepast.",
	"Noch keine eigene Vorlage gespeichert – es gilt der Standardtext.": "Nog geen eigen sjabloon opgeslagen – de standaardtekst geldt.",
	"Standardtext wiederherstellen": "Standaardtekst herstellen",
	"Die Vorlage konnte nicht geladen werden": "Het sjabloon kon niet worden geladen",
	"Willkommens-Mail senden": "Welkomstmail verzenden",
	"Geht an {email}. Der Text kommt aus der Vorlage der Einstellungen und lässt sich hier für diese eine Mail anpassen.": "Gaat naar {email}. De tekst komt uit het sjabloon in de instellingen en kan hier voor deze ene e-mail worden aangepast.",
	"Mail senden": "E-mail verzenden",
	"Willkommens-Mail gesendet.": "Welkomstmail verzonden.",
	"Betreff": "Onderwerp",
	"Text": "Tekst",
	"Platzhalter, die beim Versand ersetzt werden:": "Plaatshouders die bij het verzenden worden vervangen:",
	"Das Mitglied hat keine Mailadresse – die Willkommens-Mail kann nicht gesendet werden.": "Het lid heeft geen e-mailadres – de welkomstmail kan niet worden verzonden.",
	"Die Willkommens-Mail konnte nicht gesendet werden: %s": "De welkomstmail kon niet worden verzonden: %s",
	"Die Willkommens-Mail konnte nicht gesendet werden.": "De welkomstmail kon niet worden verzonden.",
	"Willkommen bei {verein}": "Welkom bij {verein}",
	"Guten Tag {name},\n\nwillkommen bei {verein}! Schön, dass Sie dabei sind.\n\nBei Fragen melden Sie sich gern beim Vorstand.": "Beste {name},\n\nwelkom bij {verein}! Fijn dat u erbij bent.\n\nMet vragen kunt u altijd terecht bij het bestuur.",
	"Betreff und Text der Willkommens-Mail dürfen nicht leer sein.": "Onderwerp en tekst van de welkomstmail mogen niet leeg zijn.",
	"Der Betreff ist zu lang (höchstens %d Zeichen).": "Het onderwerp is te lang (maximaal %d tekens).",
	"Der Text ist zu lang (höchstens %d Zeichen).": "De tekst is te lang (maximaal %d tekens).",
	"Unbekannter Platzhalter {%1$s}. Erlaubt sind: %2$s": "Onbekende plaatshouder {%1$s}. Toegestaan zijn: %2$s",
	"Die Mitgliederliste zeigt in der neuen Spalte „Nextcloud-Konto?\", wer verknüpft ist, und schlägt passende Konten zum Verknüpfen vor.": "De ledenlijst toont in de nieuwe kolom “Nextcloud-account?” wie gekoppeld is, en stelt passende accounts voor om te koppelen.",
	"Nextcloud-Administratoren können ein Mitglied beim Aufnehmen gleich mit einem Nextcloud-Konto anlegen – mit Einladung per Mail oder festem Passwort.": "Nextcloud-beheerders kunnen bij het opnemen van een lid meteen een Nextcloud-account aanmaken – met een uitnodiging per e-mail of een vast wachtwoord.",
	"Die neue Willkommens-Mail (Vorlage in den Einstellungen) geht beim Aufnehmen oder später aus der Akte an die Adresse des Mitglieds.": "De nieuwe welkomstmail (sjabloon in de instellingen) gaat bij het opnemen of later vanuit het dossier naar het adres van het lid.",
	"Den Standard-Beitrag in den Einstellungen gibt es nicht mehr – Betrag und Turnus kommen von der Beitragsgruppe.": "De standaardcontributie in de instellingen bestaat niet meer – bedrag en frequentie komen van de contributiegroep.",
	"Kontenblatt als CSV exportieren": "Grootboekkaart als CSV exporteren",
	"Druckfertiges Kontenblatt (öffnet in neuem Tab, dort drucken oder als PDF speichern)": "Afdrukklare grootboekkaart (opent in een nieuw tabblad; daar afdrukken of als PDF opslaan)",
