	"Der Kommentar darf höchstens %d Zeichen lang sein.": "De opmerking mag maximaal %d tekens lang zijn.",
	"Buchungen können einen Kommentar tragen, etwa für die Kassenprüfung – auch im abgeschlossenen Geschäftsjahr noch änderbar.": "Boekingen kunnen een opmerking bevatten, bijv. voor de kascontrole – ook in een afgesloten boekjaar nog te wijzigen.",
	"Das Kontenblatt eines Kontos gibt es jetzt als CSV und als druckfertige Seite (Reiter Konten, neben den Summen).": "De grootboekkaart van een rekening is nu beschikbaar als CSV en als afdrukklare pagina (tabblad Rekeningen, naast de totalen).",
	"Die Tabelle im Kontoauszug lässt sich per Klick auf die Spaltenüberschrift sortieren.": "De tabel in het rekeningafschrift kan worden gesorteerd door op een kolomkop te klikken.",
	"Kommentare an Buchungen (z. B. Hinweise der Kassenprüfung) erscheinen in den Listen als Symbol; beim Daraufzeigen steht der Text.": "Opmerkingen bij boekingen (bijv. notities van de kascontrole) verschijnen in de lijsten als pictogram; als u de muis erboven houdt, verschijnt de tekst.",
	"Die Spalte „Aktuell\" zeigt den heutigen Planwert, „Δ\" die Abweichung des aktuellen Plans zum Stand. Oberkonten zeigen die Summe ihrer Unterkonten.": "De kolom “Actueel” toont de huidige begrotingswaarde, “Δ” het verschil tussen de huidige begroting en deze versie. Hoofdrekeningen tonen het totaal van hun subrekeningen.",
	"_{count} Plankonflikt: In einem Zweig ist auf mehreren Ebenen geplant, die Summen zählen diese Pläne doppelt. Setzen Sie einen der Werte auf 0._::_{count} Plankonflikte: In einem Zweig ist auf mehreren Ebenen geplant, die Summen zählen diese Pläne doppelt. Setzen Sie jeweils einen der Werte auf 0._": [
		"{count} begrotingsconflict: in een tak is op meerdere niveaus begroot, waardoor de totalen deze bedragen dubbel tellen. Zet een van de waarden op 0.",
		"{count} begrotingsconflicten: in een tak is op meerdere niveaus begroot, waardoor de totalen deze bedragen dubbel tellen. Zet telkens een van de waarden op 0."
	],
