	"Keine Auffälligkeiten: keine Ausgabe über Plan, keine Buchung ohne Plan.": "Geen aandachtspunten: geen uitgaven boven begroting, geen boekingen zonder begroting.",
	"Planwert; bei Konten mit Unterkonten die Summe der Pläne darunter": "Begrotingswaarde; bij rekeningen met subrekeningen het totaal van de begrotingen daaronder",
	"Tatsächliche Buchungen inkl. Unterkonten": "Werkelijke boekingen incl. subrekeningen",
	"Plankonflikt": "Begrotingsconflict",
	"ohne Plan": "zonder begroting",
	"ungeplant darunter": "onbegroot daaronder",
	"Plan liegt auf {number} {name}": "Begroot op {number} {name}",
	"davon direkt {amount}": "waarvan direct {amount}",
	"Drucken / PDF": "Afdrukken / PDF",
	"Soll-Ist-Vergleich drucken": "Begroting vs. werkelijk afdrukken",
	"Planen Sie je Konto die erwarteten Einnahmen und Ausgaben (Spalte „Plan\"). Geplant wird je Zweig auf genau einer Ebene – ein Oberkonto zeigt die Summe der Pläne darunter. „Ist\" zeigt die tatsächlichen Buchungen des gewählten Zeitraums einschließlich aller Unterkonten, „Differenz\" den Abstand zum Plan.": "Begroot per rekening de verwachte inkomsten en uitgaven (kolom “Begroting”). Per tak wordt op precies één niveau begroot – een hoofdrekening toont het totaal van de begrotingen daaronder. “Werkelijk” toont de werkelijke boekingen van de gekozen periode inclusief alle subrekeningen, “Verschil” de afwijking van de begroting.",
	"Nur Kontengruppen": "Alleen rekeninggroepen",
	"Bis zur 2. Ebene": "Tot niveau 2",
	"Bis zur 3. Ebene": "Tot niveau 3",
	"Alle Unterkonten": "Alle subrekeningen",
	"In diesem Zweig ist bereits auf %1$s %2$s geplant. Je Zweig gibt es nur eine Planungsebene.": "In deze tak is al begroot op %1$s %2$s. Per tak is er maar één begrotingsniveau.",
	"Soll-Ist-Vergleich %s": "Begroting vs. werkelijk %s",
	"_%n Plankonflikt: In einem Zweig ist auf mehreren Ebenen geplant, die Summen zählen diese Pläne doppelt._::_%n Plankonflikte: In einem Zweig ist auf mehreren Ebenen geplant, die Summen zählen diese Pläne doppelt._": [
		"%n begrotingsconflict: in een tak is op meerdere niveaus begroot, waardoor de totalen deze bedragen dubbel tellen.",
		"%n begrotingsconflicten: in een tak is op meerdere niveaus begroot, waardoor de totalen deze bedragen dubbel tellen."
	],
