	"Alle Ebenen": "Alle niveaus",
	"Bis Ebene %s": "Tot niveau %s",
	"Ausgaben über Plan": "Uitgaven boven begroting",
	"Ist ohne Plan": "Werkelijk zonder begroting",
	"ungeplante Buchungen in Unterkonten": "onbegrote boekingen in subrekeningen",
	"Plan und Ist schließen alle Unterkonten ein.": "Begroting en werkelijk omvatten alle subrekeningen.",
	"Unterkonten von {number} {name} einklappen": "Subrekeningen van {number} {name} inklappen",
	"Unterkonten von {number} {name} aufklappen": "Subrekeningen van {number} {name} uitklappen",
	"Ist/Plan": "Werkelijk/begroting",
	"Verglichen wird beim Oberkonto mit dem Plan": "Vergeleken wordt met de begroting op de hoofdrekening",
	"Der Finanzplan rechnet Plan und Ist über die Unterkonten zusammen: Steht der Plan auf einem Sammelkonto, zählen die Buchungen der Unterkonten mit. Überschreitungen und Buchungen ohne Plan sind markiert.": "De begroting telt begroting en werkelijk op over de subrekeningen: staat de begroting op een verzamelrekening, dan tellen de boekingen van de subrekeningen mee. Overschrijdingen en boekingen zonder begroting zijn gemarkeerd.",
	"Geplant wird je Zweig auf genau einer Ebene. Der Finanzplan öffnet bis zu dieser Planungsebene und lässt sich auf Auffälligkeiten filtern.": "Per tak wordt op precies één niveau begroot. De begroting opent tot aan dit begrotingsniveau en kan worden gefilterd op aandachtspunten.",
	"Den Soll-Ist-Vergleich gibt es als druckfertige Seite für den Vorstand; auch der Kassenbericht vergleicht jetzt bis zur Planungsebene.": "Begroting vs. werkelijk is beschikbaar als afdrukklare pagina voor het bestuur; ook het kasverslag vergelijkt nu tot aan het begrotingsniveau.",
	"Achtung: Im CSV-Export des Finanzplans hat sich die Spaltenfolge geändert.": "Let op: in de CSV-export van de begroting is de kolomvolgorde gewijzigd.",
