	"Inhalt umstellen": "Inhoud wijzigen",
	"Die Unterabschnitte dieses Abschnitts gehen dabei verloren.": "De subsecties van deze sectie gaan daarbij verloren.",
	"Die Gliederungsebenen dieses Abschnitts gehen dabei verloren.": "De indelingsniveaus van deze sectie gaan daarbij verloren.",
