	"Plannotizen als Erläuterung unter dem Konto": "Begrotingsnotities als toelichting onder de rekening",
	"Gesamtzeile am Ende (Einnahmen − Ausgaben)": "Totaalregel aan het eind (inkomsten − uitgaven)",
	"Abschnitte schränken die Konten nach Kontoart, Sphäre oder Gruppe ein und können weitere Abschnitte enthalten. Gliederungsebenen teilen die Konten eines Abschnitts weiter auf; „Konto“ zeigt sie einzeln als Baum.": "Secties beperken de rekeningen op rekeningsoort, sfeer of groep en kunnen verdere secties bevatten. Indelingsniveaus verdelen de rekeningen van een sectie verder; “Rekening” toont ze afzonderlijk als boomstructuur.",
	"Gliederungsvorschau": "Voorbeeld van de indeling",
	"Spalte {n}": "Kolom {n}",
	"Periode": "Periode",
	"Spalte {n} nach links": "Kolom {n} naar links",
	"Spalte {n} nach rechts": "Kolom {n} naar rechts",
	"Spalte {n} löschen": "Kolom {n} verwijderen",
	"Spalte hinzufügen": "Kolom toevoegen",
	"Ohne Eintrag ist jede Auswertungsgruppe eine eigene Gruppe. Hier lassen sich Gruppen umbenennen, mehrere zusammenfassen oder einzelne Konten (samt Unterkonten) einer anderen Gruppe zuordnen. Ein ausdrücklich zugeordnetes Konto geht vor seiner Auswertungsgruppe.": "Zonder invoer is elke rapportagegroep een eigen groep. Hier kunt u groepen hernoemen, meerdere samenvoegen of afzonderlijke rekeningen (inclusief subrekeningen) aan een andere groep toewijzen. Een expliciet toegewezen rekening gaat voor op haar rapportagegroep.",
