	"CSV": "CSV",
	"Derselbe Plan und dieselben Buchungen, gegliedert nach einer Vorlage – etwa für einen Zuwendungsgeber oder für die Mitgliederversammlung. Die Vorlage legt fest, nach welchen Merkmalen gegliedert wird und welche Spalten erscheinen.": "Dezelfde begroting en dezelfde boekingen, ingedeeld volgens een sjabloon – bijvoorbeeld voor een subsidieverstrekker of voor de algemene ledenvergadering. Het sjabloon bepaalt op welke criteria wordt ingedeeld en welke kolommen verschijnen.",
