	"Eine Spalte kann höchstens %d Perioden zurückliegen.": "Een kolom kan maximaal %d perioden teruggaan.",
	"Höchstens %d Berichtsgruppen sind möglich.": "Maximaal %d rapportgroepen zijn mogelijk.",
	"Die Berichtsgruppe „%s“ ist doppelt angelegt.": "De rapportgroep “%s” bestaat twee keer.",
	"Die Berichtsgruppe „%s“ enthält zu viele Konten.": "De rapportgroep “%s” bevat te veel rekeningen.",
	"Die Auswertungsgruppe „%s“ ist mehreren Berichtsgruppen zugeordnet.": "De rapportagegroep “%s” is aan meerdere rapportgroepen toegewezen.",
	"Abschnitte lassen sich höchstens %d Ebenen tief verschachteln.": "Secties kunnen maximaal %d niveaus diep worden genest.",
