	"Abweichend": "Afwijkend",
	"Termin ändern": "Datum wijzigen",
	"Zurücksetzen": "Opnieuw instellen",
	"Termine werden berechnet …": "Data worden berekend…",
	"Änderungen noch nicht gespeichert.": "Wijzigingen nog niet opgeslagen.",
	"Bitte ein Datum wählen.": "Kies een datum.",
	"Die Termine konnten nicht berechnet werden": "De data konden niet worden berekend",
	"Je Turnus gilt ein Einzugstag, gezählt in Tagen ab Beginn jeder Periode. Einzelne Perioden können einen abweichenden Termin bekommen; er gilt in jedem Beitragsjahr für dieselbe Periode.": "Per frequentie geldt één incassodag, geteld in dagen vanaf het begin van elke periode. Afzonderlijke perioden kunnen een afwijkende datum krijgen; die geldt in elk contributiejaar voor dezelfde periode.",
	"Tritt ein Mitglied mitten in einer Periode ein, zählen die Tage für seine erste Forderung ab dem Eintrittsdatum.": "Treedt een lid midden in een periode toe, dan tellen de dagen voor zijn eerste vordering vanaf de toetredingsdatum.",
