	"Möglich sind bis zu {before} Tage vor und {after} Tage nach Periodenbeginn.": "Mogelijk zijn maximaal {before} dagen vóór en {after} dagen na het begin van de periode.",
	"{n}. Quartal": "Kwartaal {n}",
