	"{n}. Periode": "Periode {n}",
	"In Jahren ohne 29. Februar liegt dieser Termin einen Tag später: Gespeichert wird der Abstand zum Periodenbeginn.": "In jaren zonder 29 februari valt deze datum een dag later: opgeslagen wordt de afstand tot het begin van de periode.",
	"In Jahren ohne 29. Februar liegt dieser Termin einen Tag früher: Gespeichert wird der Abstand zum Periodenbeginn.": "In jaren zonder 29 februari valt deze datum een dag eerder: opgeslagen wordt de afstand tot het begin van de periode.",
	"In Schaltjahren liegt dieser Termin einen Tag früher: Gespeichert wird der Abstand zum Periodenbeginn.": "In schrikkeljaren valt deze datum een dag eerder: opgeslagen wordt de afstand tot het begin van de periode.",
	"In Schaltjahren liegt dieser Termin einen Tag später: Gespeichert wird der Abstand zum Periodenbeginn.": "In schrikkeljaren valt deze datum een dag later: opgeslagen wordt de afstand tot het begin van de periode.",
	"{periodName}: Der Einzug am {date} läge außerhalb des Beitragsjahrs ({from} bis {to}).": "{periodName}: de incasso op {date} zou buiten het contributiejaar vallen ({from} tot {to}).",
	"{periodName}: Der Einzug am {date} läge nicht nach dem Einzug für {previous} am {previousDate}.": "{periodName}: de incasso op {date} zou niet na de incasso voor {previous} op {previousDate} vallen.",
