	"Es entsteht eine Stornorechnung, die alle Positionen umkehrt und auf die Rechnung verweist. Die Rechnung gilt danach als storniert. Das lässt sich nicht rückgängig machen.": "Er wordt een creditnota aangemaakt die alle regels omkeert en naar de factuur verwijst. De factuur geldt daarna als gecrediteerd. Dit kan niet ongedaan worden gemaakt.",
	"Es sind bereits {amount} eingegangen. Die Zahlung bleibt gebucht; die Rückzahlung ordnen Sie später wie jede Auszahlung dem Erlöskonto zu.": "Er is al {amount} ontvangen. De betaling blijft geboekt; de terugbetaling wijst u later, zoals elke uitbetaling, toe aan de opbrengstrekening.",
