	"Es fehlen noch Angaben: {list}": "Er ontbreken nog gegevens: {list}",
	"Die Rechnung konnte nicht festgeschrieben werden.": "De factuur kon niet definitief worden gemaakt.",
	"Der Entwurf konnte nicht gelöscht werden.": "Het concept kon niet worden verwijderd.",
	"Rechnung festschreiben": "Factuur definitief maken",
	"Beim Festschreiben bekommt die Rechnung ihre Nummer, und die Anschrift des Empfängers wird übernommen. Danach lässt sie sich nicht mehr ändern, nur noch stornieren. Gleichzeitig entsteht der offene Posten.": "Bij het definitief maken krijgt de factuur haar nummer en wordt het adres van de ontvanger overgenomen. Daarna kan ze niet meer worden gewijzigd, alleen nog worden gecrediteerd. Tegelijk ontstaat de openstaande post.",
	"Prüfung der Pflichtangaben": "Controle van de verplichte gegevens",
	"(empfohlen)": "(aanbevolen)",
	"Die Rechnungsnummer folgt aus dem Nummernkreis und dem Jahr dieses Datums.": "Het factuurnummer volgt uit de nummerreeks en het jaar van deze datum.",
	"Jetzt festschreiben": "Nu definitief maken",
