	"Noch offen: {amount}. Eine Teilzahlung ist möglich; sie wird anteilig auf die Erlöskonten der Positionen gebucht.": "Nog openstaand: {amount}. Een deelbetaling is mogelijk; deze wordt naar rato op de opbrengstrekeningen van de factuurregels geboekt.",
	"Bankumsatz zuordnen": "Banktransactie toewijzen",
	"Barzahlung buchen": "Contante betaling boeken",
	"Es gibt keinen unzugeordneten Zahlungseingang. Importieren Sie zuerst den Kontoauszug.": "Er is geen niet-toegewezen ontvangen betaling. Importeer eerst het bankafschrift.",
	"Unzugeordnete Zahlungseingänge": "Niet-toegewezen ontvangen betalingen",
	"Der Betrag übersteigt den offenen Rest. Teilen Sie den Umsatz in „Buchungen → Zuzuordnen“ auf und ordnen Sie den Rest einem anderen Konto zu.": "Het bedrag is hoger dan het openstaande restant. Splits de transactie in “Boekingen → Toe te wijzen” en wijs het restant toe aan een andere rekening.",
	"Das ist eine Teilzahlung. Die Rechnung bleibt offen, bis der Rest eingeht.": "Dit is een deelbetaling. De factuur blijft openstaan tot het restant binnenkomt.",
	"Zahlungsdatum": "Betaaldatum",
	"Eingegangen auf": "Ontvangen op",
	"– Geldkonto wählen –": "– Kies geldrekening –",
	"Gebucht wird: Geldkonto an die Erlöskonten der Positionen. Für Zahlungen, die über einen Kontoauszug kommen, nutzen Sie stattdessen „Bankumsatz zuordnen“.": "Geboekt wordt: geldrekening aan de opbrengstrekeningen van de factuurregels. Gebruik voor betalingen die via een bankafschrift binnenkomen in plaats daarvan “Banktransactie toewijzen”.",
	"Zahlung buchen": "Betaling boeken",
