	"Rechnungen durchsuchen": "Facturen doorzoeken",
	"Für Rechnungen fehlen noch Angaben des Vereins (Anschrift, Steuernummer). Tragen Sie sie in den Nextcloud-Einstellungen unter „Vereinsbuchhaltung“ ein.": "Voor facturen ontbreken nog gegevens van de vereniging (adres, belastingnummer). Vul deze in bij de Nextcloud-instellingen onder “Vereinsbuchhaltung”.",
	"Davon überfällig": "Waarvan achterstallig",
	"Noch keine Rechnungen": "Nog geen facturen",
	"Hier stellen Sie Rechnungen im Namen des Vereins aus, zum Beispiel für Hallenmiete, Kursgebühren oder Sponsoring. Jede festgeschriebene Rechnung erscheint als offener Posten und wird beim Kontoauszug-Import automatisch ihrer Zahlung zugeordnet.": "Hier stelt u facturen op namens de vereniging, bijvoorbeeld voor zaalhuur, cursusgeld of sponsoring. Elke definitieve factuur verschijnt als openstaande post en wordt bij het importeren van het bankafschrift automatisch aan de betaling gekoppeld.",
	"Erste Rechnung schreiben": "Eerste factuur opstellen",
	"Keine Rechnung passt zu den Filtern.": "Geen enkele factuur voldoet aan de filters.",
