	"Steuer, Zahlung und Texte": "Belasting, betaling en teksten",
	"Die meisten kleinen Vereine sind Kleinunternehmer nach § 19 UStG und weisen keine Umsatzsteuer aus. Ob das für Ihren Verein gilt, klärt das Finanzamt oder Ihre Steuerberatung.": "De meeste kleine verenigingen zijn kleine ondernemer volgens § 19 UStG (Kleinunternehmer) en vermelden geen btw. Of dat voor uw vereniging geldt, kunt u navragen bij de belastingdienst (Finanzamt) of uw belastingadviseur.",
