	"– kein Konto –": "– geen rekening –",
	"Ablageordner für Rechnungs-Dateien": "Opslagmap voor factuurbestanden",
	"Die PDFs liegen als Dateien im Ordner des Nutzers der Belegablage, jeweils in einem Unterordner je Jahr. Ist keiner eingerichtet, speichert die App sie intern.": "De PDF's worden als bestanden opgeslagen in de map van de gebruiker die voor de opslag van bewijsstukken is ingesteld, telkens in een submap per jaar. Is er geen ingesteld, dan slaat de app ze intern op.",
	"Die PDFs liegen in dessen Home unter": "De PDF's staan in de thuismap van die gebruiker onder",
	"Der Pfad beginnt im Home dieses Nutzers, nicht in Ihrem eigenen; ein fehlender Ordner wird angelegt. Am sichersten wählen Sie den Ordner über den Knopf neben dem Feld.": "Het pad begint in de thuismap van deze gebruiker, niet in uw eigen map; een ontbrekende map wordt aangemaakt. Het veiligst kiest u de map met de knop naast het veld.",
	"E-Mail-Vorlage für den Versand": "E-mailsjabloon voor verzending",
