	"Die Datei ließ sich nicht lesen.": "Het bestand kon niet worden gelezen.",
	"Bitte einen Namen für das Projekt angeben.": "Vul een naam voor het project in.",
	"Die Tabelle enthält keine fehlerfreie Rechnung.": "De spreadsheet bevat geen foutloze factuur.",
	"Das Projekt enthält schon festgeschriebene Rechnungen und lässt sich nicht mehr löschen.": "Het project bevat al definitieve facturen en kan niet meer worden verwijderd.",
	"Für den Leistungszeitraum bitte Beginn und Ende angeben.": "Vul voor de leveringsperiode een begin en een einde in.",
	"Mindestens eine Position hat kein Erlöskonto – zum Festschreiben nötig (Spalte „Erlöskonto“, Vorlage oder Vorgabe im Dialog).": "Ten minste één factuurregel heeft geen opbrengstrekening – nodig om definitief te maken (kolom “Revenue account”, sjabloon of standaardwaarde in het dialoogvenster).",
	"Kein Leistungsdatum – zum Festschreiben nötig (Spalte „Leistungsdatum“ oder Vorgabe im Dialog).": "Geen leveringsdatum – nodig om definitief te maken (kolom “Delivery date” of standaardwaarde in het dialoogvenster).",
