	"Der Verein überweist an diesen Kontoinhaber. Soll das Geld auf das Konto einer anderen Person gehen, tragen Sie deren Namen ein.": "De vereniging maakt het geld over naar deze rekeninghouder. Moet het geld naar de rekening van iemand anders gaan, vul dan diens naam in.",
	"Erklärung": "Verklaring",
	"Zweck": "Doel",
	"Ich versichere, dass die Auslagen im Auftrag des Vereins entstanden sind, von mir bezahlt wurden und nicht anderweitig erstattet wurden.": "Ik verklaar dat de onkosten in opdracht van de vereniging zijn gemaakt, door mij zijn betaald en niet op een andere manier zijn vergoed.",
	"Bitte bestätigen Sie die Erklärung.": "Bevestig de verklaring.",
	"Mehrere Rechnungen? Reichen Sie jede als eigenen Antrag ein. Mit „Einreichen und weitere erfassen“ bleiben Kontoverbindung und Erklärung ausgefüllt.": "Meerdere facturen? Dien elke factuur in als aparte aanvraag. Met “Indienen en nog een toevoegen” blijven bankgegevens en verklaring ingevuld.",
	"Einreichen und weitere erfassen": "Indienen en nog een toevoegen",
	"Neu: Sammelrechnungen. Unter „Rechnungen → Aus Tabelle einlesen“ legt eine Excel- oder CSV-Datei für jeden Empfänger einen Rechnungsentwurf an.": "Nieuw: verzamelfacturen. Onder “Facturen → Uit spreadsheet inlezen” maakt een Excel- of CSV-bestand voor elke ontvanger een conceptfactuur aan.",
	"Neu: Rechnungsnummern können den Monat enthalten ({MM}) und jeden Monat neu bei 1 beginnen.": "Nieuw: factuurnummers kunnen de maand bevatten ({MM}) en elke maand opnieuw bij 1 beginnen.",
	"Auslagen: Rechnungsnummer, Lieferant und Kontoinhaber, dazu eine Erklärung. Mehrere Rechnungen gehen nacheinander.": "Declaraties: factuurnummer, leverancier en rekeninghouder, plus een verklaring. Meerdere facturen kunnen na elkaar worden ingevoerd.",
