	"Kostenstelle": "Kostenplaats",
	"Einnahmen, Ausgaben und Ergebnis je Kostenstelle – nach den Beträgen, die beim Buchen zugeordnet wurden. Was keiner Kostenstelle zugeordnet ist, steht unter „Ohne Kostenstelle“.": "Inkomsten, uitgaven en resultaat per kostenplaats – op basis van de bedragen die bij het boeken zijn toegewezen. Wat aan geen kostenplaats is toegewezen, staat onder ‘Zonder kostenplaats’.",
