	"Bericht je Kostenstelle als CSV exportieren": "Rapport per kostenplaats als CSV exporteren",
	"Kostenstellen verwalten": "Kostenplaatsen beheren",
	"Mit Kostenstellen ordnen Sie einzelne Beträge einer Abteilung, Mannschaft oder einem Projekt zu – auch anteilig: von 1.000 für Ausrüstung gehen 600 an die Senioren und 400 an die A-Junioren, auf demselben Konto. Ein eigener Bericht zeigt Einnahmen, Ausgaben und Ergebnis je Kostenstelle.": "Met kostenplaatsen wijst u afzonderlijke bedragen toe aan een afdeling, een team of een project – ook in delen: van 1.000 voor uitrusting gaat 600 naar de senioren en 400 naar de A-junioren, op dezelfde rekening. Een eigen rapport toont inkomsten, uitgaven en resultaat per kostenplaats.",
	"Kostenstellen aktivieren": "Kostenplaatsen inschakelen",
	"Schaltet das Feld „Kostenstelle“ beim Buchen und den Bericht „Kostenstellen“ ein. Die Angabe bleibt bei jeder Buchung freiwillig. Ausgeschaltet ist von der Funktion nichts zu sehen; bereits gespeicherte Zuordnungen bleiben erhalten und erscheinen wieder, sobald Sie die Funktion erneut einschalten.": "Schakelt het veld ‘Kostenplaats’ bij het boeken en het rapport ‘Kostenplaatsen’ in. De opgave blijft bij elke boeking vrijwillig. Uitgeschakeld is er van de functie niets te zien; reeds opgeslagen toewijzingen blijven behouden en verschijnen weer zodra u de functie opnieuw inschakelt.",
	"Einstellungen werden geladen": "Instellingen worden geladen",
