	"Es gibt bereits eine Kostenstelle mit dem Kürzel „%s\".": "Er bestaat al een kostenplaats met de code ‘%s’.",
	"Der Kostenstelle „%s\" sind Buchungen zugeordnet. Sie lässt sich deaktivieren, aber nicht löschen.": "Aan kostenplaats ‘%s’ zijn boekingen toegewezen. Deze kan worden gedeactiveerd, maar niet verwijderd.",
	"Das Kürzel der Kostenstelle ist Pflicht.": "De code van de kostenplaats is verplicht.",
